#include <Keypad.h>

const byte ROWS = {{rows}};
const byte COLS = {{cols}};
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {{row_pins}};
byte colPins[COLS] = {{col_pins}};

Keypad kpd = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

void setup() {
  Serial.begin(115200);
}

void loop() {
  char k = kpd.getKey();
  if (k) {
    Serial.print("key=");
    Serial.println(k);
  }
}
